contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function invariant(address pool) external {
        uint b0 = c.getmapAddress_LPBalance(pool);
        uint d0 = c.getmapAddress_LPDebt(pool);
        require(d0 > 0, "no debt");
        require(b0 > 0, "no collateral");
        uint s = c.balanceOf(address(c));
        require(s > 0, "no synth held");
        require(s <= d0, "too much synth");
        bool ok = c.burnSynth();
        require(ok, "burn reverted");
        assert(c.getmapAddress_LPBalance(pool) * d0 == b0 * c.getmapAddress_LPDebt(pool));
    }

    fallback() external payable {}
}
